const empresa = $('Postgres - Obtener empresa').item.json;
const webhookData = $('Webhook empresa-context').item.json.body;
const documentosBase64 = webhookData.documentosBase64 || [];

const systemPrompt = 'Eres un asistente juridico experto en contratacion publica colombiana (SECOP II). Tu tarea es analizar el contexto de una empresa y extraer toda la informacion relevante para determinar en que licitaciones puede participar y ganar. Documentos clave por orden de importancia: 1. CUADRO DE EXPERIENCIA es el mas importante, define contratos similares ejecutados y determina que licitaciones puede ganar la empresa. 2. RUP (Registro Unico de Proponentes) contiene indicadores financieros oficiales y reemplaza los estados financieros. 3. Certificados de existencia y representacion legal de Camara de Comercio para vigencia juridica. 4. Certificados SG-SST de ARL y Ministerio de Trabajo para capacidad tecnica en seguridad laboral. 5. Antecedentes de Contraloria, Procuraduria y Judiciales para habilitacion legal. Devuelve UNICAMENTE un JSON valido con esta estructura exacta sin texto adicional sin markdown sin explicaciones: {"nombre_comercial":"string","nit":"string","sector_principal":"string","sectores_secundarios":["string"],"anos_experiencia":0,"contratos_ejecutados":[{"descripcion":"string","valor_aproximado":"string","entidad":"string","ano":"string"}],"capacidad_tecnica":"string","indicadores_financieros":{"descripcion":"string","nivel":"alto|medio|bajo"},"habilitacion_legal":"habilitada|inhabilitada|sin_verificar","fortalezas":["string"],"debilidades":["string"],"tipos_contrato_recomendados":["string"],"valor_maximo_contrato_estimado":"string","resumen_ejecutivo":"string"}';

const introText = 'Analiza esta empresa para licitaciones del SECOP II:\n\nNombre: ' + empresa.nombre + '\nNIT: ' + empresa.nit + '\nSector declarado: ' + (empresa.sector || 'No especificado') + '\n\nA continuacion se adjuntan los documentos de la empresa en PDF.';

const contentBlocks = [{ type: 'text', text: introText }];

for (const doc of documentosBase64) {
  contentBlocks.push({
    type: 'document',
    source: {
      type: 'base64',
      media_type: doc.mediaType,
      data: doc.base64
    },
    title: doc.nombre
  });
}

if (documentosBase64.length === 0) {
  contentBlocks.push({ type: 'text', text: 'Contexto adicional: ' + (empresa.contexto_raw || 'Sin documentos adjuntos.') });
}

const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 2048,
  system: systemPrompt,
  messages: [{ role: 'user', content: contentBlocks }]
};

return [{
  json: {
    empresaId: webhookData.empresaId,
    claudeBody: JSON.stringify(requestBody)
  }
}];

const response = $('Claude API - Analizar empresa').item.json;
const empresaId = $('Code - Build Claude Request').item.json.empresaId;

let contextoTexto = '';
if (response.content && response.content[0] && response.content[0].text) {
  contextoTexto = response.content[0].text.trim();
  // Limpiar markdown si Claude lo agrega
  contextoTexto = contextoTexto.replace(/```json/g, '').replace(/```/g, '').trim();
}

// Validar que sea JSON valido
try {
  JSON.parse(contextoTexto);
} catch(e) {
  contextoTexto = JSON.stringify({ error: 'respuesta_no_valida', raw: contextoTexto.substring(0, 500) });
}

return [{ json: { empresaId, contextoTexto } }];
